(() => {
  const S={token:localStorage.getItem('mg_token')||'',profile:JSON.parse(localStorage.getItem('mg_profile')||'null'),modules:[],section:'dashboard',chats:[],activeChat:null,messages:[],ws:null,typing:null,exam:null,offline:!navigator.onLine};
  const app=document.getElementById('app'), toast=document.getElementById('toast');
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const fmt=d=>{try{return new Date(d).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}catch{return ''}};
  const roleName=r=>({WORKER:'Рабочий',MASTER:'Мастер',ENGINEER:'ИТР / Инженер',HEAD:'Руководитель',ADMIN:'Администратор'}[r]||r||'');
  const icons={dashboard:'⌂',chats:'💬',tickets:'📋',incidents:'⚠',exams:'🎓',itr_ai:'✦',payroll:'₽','1c':'1C',directum:'D',profile:'👤',admin:'⚙'};
  function notify(m,err=false){toast.textContent=m;toast.className='toast show'+(err?' err':'');clearTimeout(notify.t);notify.t=setTimeout(()=>toast.className='toast',3000)}
  function authHeaders(extra={}){return {...extra,Authorization:`Bearer ${S.token}`}}
  async function api(path,opt={}){const o={...opt,headers:authHeaders(opt.headers||{})};if(o.body&&!(o.body instanceof FormData)&&typeof o.body!=='string'){o.headers['Content-Type']='application/json';o.body=JSON.stringify(o.body)}const r=await fetch('/api/v1'+path,o);if(r.status===401){logout();throw new Error('Сессия завершена')}if(!r.ok){let d='';try{d=(await r.json()).detail}catch{d=await r.text()}throw new Error(d||`Ошибка ${r.status}`)}const ct=r.headers.get('content-type')||'';return ct.includes('json')?r.json():r.text()}
  function initials(){const n=S.profile?.full_name||S.profile?.id||'MG';return n.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()}
  function logout(){localStorage.removeItem('mg_token');S.token='';S.profile=null;S.modules=[];if(S.ws)S.ws.close();renderLogin()}
  function loginMarkup(){return `<div class="login-page"><section class="login-hero"><div class="brand"><div class="brand-mark">M</div><div>MINI GRAMM CORPORATE</div></div><h1 class="hero-title">Единая рабочая среда сотрудников АГМК</h1><div class="hero-sub">Корпоративные чаты, заявки, инциденты, экзамены, AI-помощник ИТР и персональные расчётные листы — в одной локальной системе.</div><div class="hero-pills"><span class="pill">Локальная сеть</span><span class="pill">Доступ по структуре</span><span class="pill">Табельный номер</span><span class="pill">Online / Offline</span></div></section><section class="login-side"><div class="login-card"><div class="brand" style="color:#071a33"><div class="brand-mark">M</div><div>Mini Gramm</div></div><h2 style="margin-top:28px">Вход для сотрудника</h2><div class="muted">Введите табельный номер и пароль.</div><form id="loginForm"><div class="field"><label>ТАБЕЛЬНЫЙ НОМЕР</label><input id="loginTab" class="input" autocomplete="username" placeholder="Например: DEMO-ADMIN" value="DEMO-ADMIN"></div><div class="field"><label>ПАРОЛЬ</label><input id="loginPass" type="password" class="input" autocomplete="current-password" placeholder="Пароль" value="demo-admin"></div><button class="btn btn-primary login-btn">Войти в Mini Gramm</button></form><div id="loginError" class="danger small" style="margin-top:12px"></div><div class="login-note">После импорта Excel учётные записи создаются автоматически. Основной идентификатор сотрудника — табельный номер.</div></div></section></div>`}
  function renderLogin(){app.innerHTML=loginMarkup();document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();const u=document.getElementById('loginTab').value.trim(),p=document.getElementById('loginPass').value;document.getElementById('loginError').textContent='';try{const body=new URLSearchParams({username:u,password:p});const r=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok){let x=await r.json().catch(()=>({detail:'Ошибка входа'}));throw new Error(x.detail||'Ошибка входа')}const d=await r.json();S.token=d.access_token;localStorage.setItem('mg_token',S.token);await bootstrap()}catch(x){document.getElementById('loginError').textContent=x.message}}}
  async function bootstrap(){try{S.profile=await api('/me/corporate');S.modules=(await api('/modules')).filter(x=>x.visible);localStorage.setItem('mg_profile',JSON.stringify(S.profile));localStorage.setItem('mg_modules',JSON.stringify(S.modules));renderShell();go('dashboard')}catch(e){const cachedModules=JSON.parse(localStorage.getItem('mg_modules')||'[]');const hasOffline=Object.keys(localStorage).some(k=>k.startsWith('mg_exam_pkg_'));if(S.profile&&hasOffline){S.offline=true;S.modules=cachedModules.length?cachedModules:[{key:'exams',title:'Экзамены Online / Offline',enabled:true,visible:true}];renderShell();go('exams');notify('Сервер недоступен. Открыт офлайн-режим экзаменов.')}else{notify(e.message,true);logout()}}}
  function navItems(){let a=[{key:'dashboard',title:'Главная'}];a.push(...S.modules.map(x=>({key:x.key,title:x.title,enabled:x.enabled,status:x.status})));a.push({key:'profile',title:'Профиль'});if(S.profile?.role==='ADMIN')a.push({key:'admin',title:'Администрирование'});return a}
  function renderShell(){app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="side-brand"><div class="brand-mark">M</div><div><div class="side-title">Mini Gramm</div><div class="side-sub">AGMK CORPORATE</div></div></div><div class="nav-title">Рабочее пространство</div><nav id="nav"></nav><div class="side-user"><div class="user-row"><div class="avatar">${esc(initials())}</div><div><div class="user-name">${esc(S.profile?.full_name||S.profile?.id)}</div><div class="user-meta">${esc(roleName(S.profile?.role))} • ${esc(S.profile?.workshop||'')}</div></div></div></div></aside><main class="main"><div id="top"></div><div id="content"></div></main></div>`;renderNav()}
  function renderNav(){const n=document.getElementById('nav');if(!n)return;n.innerHTML=navItems().map(x=>`<button class="nav-btn ${S.section===x.key?'active':''}" data-nav="${x.key}"><span class="nav-ico">${icons[x.key]||'•'}</span><span>${esc(x.title)}</span>${x.enabled===false?'<i class="nav-status"></i>':''}</button>`).join('');n.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav))}
  function top(title,kicker='MINI GRAMM CORPORATE',actions=''){document.getElementById('top').innerHTML=`<div class="topbar"><div><div class="page-kicker">${esc(kicker)}</div><div class="page-title">${esc(title)}</div></div><div class="top-actions"><span id="netState" class="online-dot ${S.offline?'offline':''}">${S.offline?'Офлайн':'Сервер доступен'}</span>${actions}<button class="btn btn-ghost" id="logoutBtn">Выйти</button></div></div>`;document.getElementById('logoutBtn').onclick=logout}
  function go(k){S.section=k;renderNav();if(S.ws){S.ws.close();S.ws=null}const m=S.modules.find(x=>x.key===k);if(m&&m.enabled===false)return renderLocked(m);({dashboard:renderDashboard,chats:renderChats,tickets:renderTickets,incidents:renderIncidents,exams:renderExams,itr_ai:renderItr,payroll:renderPayroll,profile:renderProfile,admin:renderAdmin}[k]||renderDashboard)()}
  function renderDashboard(){top('Рабочий стол');const mods=S.modules.filter(x=>x.visible!==false);document.getElementById('content').innerHTML=`<div class="grid grid-4"><div class="card metric"><div class="metric-icon">🏢</div><div class="metric-value">${esc(S.profile?.enterprise||'АГМК')}</div><div class="metric-label">Предприятие</div></div><div class="card metric"><div class="metric-icon">🏭</div><div class="metric-value" style="font-size:21px">${esc(S.profile?.workshop||'—')}</div><div class="metric-label">Цех / подразделение</div></div><div class="card metric"><div class="metric-icon">🪪</div><div class="metric-value">${esc(S.profile?.tab_no||S.profile?.id)}</div><div class="metric-label">Табельный номер</div></div><div class="card metric"><div class="metric-icon">✓</div><div class="metric-value" style="font-size:21px">${esc(roleName(S.profile?.role))}</div><div class="metric-label">Роль доступа</div></div></div><div style="height:20px"></div><div class="section-head"><h3>Разделы Mini Gramm</h3><div class="muted small">Показываются только разрешённые вашей роли</div></div><div class="grid grid-3">${mods.map(m=>`<div class="card module-card" data-module="${m.key}"><div class="module-icon">${icons[m.key]||'•'}</div><div class="module-title">${esc(m.title)}</div><div class="module-desc">${moduleDesc(m.key)}</div>${m.enabled===false?`<span class="lock-badge">${esc(m.status||'Ожидает интеграции')}</span>`:''}</div>`).join('')}</div>`;document.querySelectorAll('[data-module]').forEach(x=>x.onclick=()=>go(x.dataset.module))}
  function moduleDesc(k){return {chats:'Личные, групповые, цеховые и руководящие чаты.',tickets:'Рабочие заявки и контроль исполнения.',incidents:'Регистрация происшествий и событий.',exams:'Экзаменационная часть с offline-пакетами.',itr_ai:'Поиск информации по техническим документам.',payroll:'Только ваши персональные расчётные листы.','1c':'Подготовленный раздел будущей интеграции.','directum':'Подготовленный раздел будущей интеграции.'}[k]||''}
  function renderLocked(m){top(m.title);document.getElementById('content').innerHTML=`<div class="card" style="max-width:720px;padding:34px"><div class="module-icon">🔒</div><h2>${esc(m.title)}</h2><p class="muted">${esc(m.status||'Модуль пока не активирован.')}</p><div class="offline-banner">Раздел уже заложен в архитектуру Mini Gramm, но реальные корпоративные данные и действия не подключаются до официального разрешения и интеграции.</div></div>`}

  async function renderChats(){top('Чаты','КОРПОРАТИВНАЯ СВЯЗЬ',`<button class="btn btn-soft" id="newDirect">+ Личный чат</button><button class="btn btn-primary" id="aiGroup">✦ Создать группу</button>`);document.getElementById('content').innerHTML=`<div class="chat-layout"><aside class="chat-list"><div class="chat-list-head"><div class="chat-search"><input id="chatQ" class="input" placeholder="Поиск чата"><button id="msgSearch" class="btn btn-ghost">⌕</button></div></div><div id="chatItems" class="chat-items"><div class="empty">Загрузка...</div></div></aside><section class="chat-pane"><div id="chatHead" class="chat-pane-head"><b>Выберите чат</b></div><div id="messages" class="messages"><div class="empty"><div class="empty-icon">💬</div>Выберите чат слева</div></div><div id="typing" class="typing"></div><div class="composer"><input id="fileInput" type="file" hidden><button id="fileBtn" class="btn btn-ghost">📎</button><textarea id="msgText" class="textarea" placeholder="Сообщение..." style="min-height:44px"></textarea><button id="sendBtn" class="btn btn-primary">Отправить</button></div></section></div>`;document.getElementById('newDirect').onclick=openDirect;document.getElementById('aiGroup').onclick=openAiGroup;document.getElementById('msgSearch').onclick=searchMessages;document.getElementById('fileBtn').onclick=()=>document.getElementById('fileInput').click();document.getElementById('fileInput').onchange=e=>uploadChatFile(e.target.files[0]);document.getElementById('sendBtn').onclick=sendMessage;document.getElementById('msgText').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}else sendTyping()};document.getElementById('chatQ').oninput=drawChats;try{S.chats=await api('/chats');drawChats();if(S.chats.length)openChat(S.chats[0].id)}catch(e){notify(e.message,true)}}
  function drawChats(){const q=(document.getElementById('chatQ')?.value||'').toLowerCase();const rows=S.chats.filter(x=>(x.title||'').toLowerCase().includes(q));document.getElementById('chatItems').innerHTML=rows.length?rows.map(c=>`<div class="chat-item ${S.activeChat?.id===c.id?'active':''}" data-chat="${c.id}"><div class="chat-bubble">${c.title?.includes('директор')?'🔒':'💬'}</div><div class="chat-info"><div class="chat-title">${esc(c.title)}</div><div class="chat-meta">${esc(c.department_id||'')} ${c.section_id?`• ${esc(c.section_id)}`:''}</div></div>${c.unread_count?`<span class="unread">${c.unread_count}</span>`:''}</div>`).join(''):'<div class="empty">Чатов нет</div>';document.querySelectorAll('[data-chat]').forEach(x=>x.onclick=()=>openChat(Number(x.dataset.chat)))}
  async function openChat(id){try{const d=await api(`/chats/${id}`);S.activeChat=d;S.messages=d.messages||[];drawChats();document.getElementById('chatHead').innerHTML=`<div><b>${esc(d.title||S.chats.find(x=>x.id===id)?.title||'Чат')}</b><div class="small muted">${S.messages.length} сообщений</div></div>`;drawMessages();connectWS(id);const last=S.messages.at(-1)?.id;if(last)api(`/chats/${id}/read`,{method:'POST',body:{last_read_id:last}}).catch(()=>{})}catch(e){notify(e.message,true)}}
  function drawMessages(){const el=document.getElementById('messages');if(!el)return;el.innerHTML=S.messages.length?S.messages.map(m=>{if(m.user_id==='SYSTEM')return `<div class="msg msg-system">${esc(m.text)}</div>`;const mine=m.user_id===S.profile?.id;return `<div class="msg ${mine?'mine':''}"><div class="msg-author">${mine?'Вы':esc(m.user_id)}</div><div>${esc(m.text||'')}</div>${(m.attachments||[]).map(a=>`<a class="file-link" href="/api/v1/files/${a.id}" target="_blank" onclick="event.preventDefault();window.downloadAttachment(${a.id},'${esc(a.name)}')">📎 ${esc(a.name)}</a>`).join('')}<div class="msg-time">${fmt(m.created_at)}</div></div>`}).join(''):'<div class="empty">Сообщений пока нет</div>';el.scrollTop=el.scrollHeight}
  window.downloadAttachment=async(id,name)=>{try{const r=await fetch(`/api/v1/files/${id}`,{headers:authHeaders()});if(!r.ok)throw new Error('Не удалось скачать файл');const b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name||'file';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}catch(e){notify(e.message,true)}};
  async function sendMessage(){const input=document.getElementById('msgText'),t=input?.value.trim();if(!S.activeChat||!t)return;try{await api(`/chats/${S.activeChat.id}/messages`,{method:'POST',body:{text:t}});input.value='';await openChat(S.activeChat.id)}catch(e){notify(e.message,true)}}
  async function uploadChatFile(f){if(!f||!S.activeChat)return;const fd=new FormData();fd.append('file',f);fd.append('text','📎 '+f.name);try{await api(`/chats/${S.activeChat.id}/upload`,{method:'POST',body:fd});await openChat(S.activeChat.id)}catch(e){notify(e.message,true)}}
  function connectWS(id){if(S.ws)S.ws.close();const proto=location.protocol==='https:'?'wss':'ws';const ws=new WebSocket(`${proto}://${location.host}/api/v1/ws/chat/${id}?token=${encodeURIComponent(S.token)}`);S.ws=ws;ws.onmessage=e=>{try{const d=JSON.parse(e.data);if(d.type==='message'&&d.message&&!S.messages.some(x=>x.id===d.message.id)){S.messages.push(d.message);drawMessages()}if(d.type==='typing'&&d.user_id!==S.profile.id){document.getElementById('typing').textContent=`${d.user_id} печатает...`;clearTimeout(S.typing);S.typing=setTimeout(()=>{const x=document.getElementById('typing');if(x)x.textContent=''},1800)}}catch{}}}
  function sendTyping(){if(S.ws?.readyState===1)try{S.ws.send(JSON.stringify({type:'typing'}))}catch{}}
  async function openDirect(){try{const users=await api('/directory/users?limit=200');modal('Новый личный чат',`<div class="field"><label>СОТРУДНИК</label><select id="directUser" class="select">${users.filter(x=>x.id!==S.profile.id).map(x=>`<option value="${esc(x.id)}">${esc(x.full_name)} — ${esc(x.id)}</option>`).join('')}</select></div><button id="createDirectBtn" class="btn btn-primary">Создать чат</button>`);document.getElementById('createDirectBtn').onclick=async()=>{try{const r=await api('/chats/direct',{method:'POST',body:{user_id:document.getElementById('directUser').value}});closeModal();S.chats=await api('/chats');drawChats();openChat(r.id)}catch(e){notify(e.message,true)}}}catch(e){notify(e.message,true)}}
  async function openAiGroup(){modal('AI Chat Builder',`<div class="field"><label>ОПИШИТЕ ЧАТ ОБЫЧНЫМИ СЛОВАМИ</label><textarea id="gPrompt" class="textarea" placeholder="Например: Создай чат для мастеров моего цеха — ремонт мельницы №3"></textarea></div><div class="muted small">AI-шаблон определит тип участников и создаст группу только в пределах разрешённой вам структуры. Можно написать: рабочие, мастера, ИТР/инженеры или все сотрудники цеха.</div><button id="buildGroup" class="btn btn-primary" style="margin-top:16px">✦ Создать чат по запросу</button>`);document.getElementById('buildGroup').onclick=async()=>{try{const promptText=val('gPrompt');if(!promptText)return notify('Опишите, какой чат создать',true);const low=promptText.toLowerCase();let role=null;if(/мастер/.test(low))role='MASTER';else if(/инженер|итр|технолог|механик|энергетик/.test(low))role='ENGINEER';else if(/рабоч|электромонт|слесар|оператор/.test(low))role='WORKER';let title=promptText.replace(/^\s*(создай|создать|сделай)\s+(мне\s+)?(группу|чат)\s*(для|по)?\s*/i,'').trim();if(title.length>80)title=title.slice(0,80);if(!title)title='Рабочая группа';const r=await api('/ai/chat-builder',{method:'POST',body:{title,role_key:role}});closeModal();S.chats=await api('/chats');drawChats();openChat(r.id);notify(`Чат создан. Участников: ${r.members}`)}catch(e){notify(e.message,true)}}}
  async function searchMessages(){const term=prompt('Что найти в сообщениях?');if(!term||term.trim().length<2)return;try{const h=await api(`/search/messages?q=${encodeURIComponent(term.trim())}`);modal('Результаты поиска',h.length?h.slice(0,30).map(x=>`<div class="source" data-hit="${x.chat_id}" style="cursor:pointer"><b>${esc(x.chat_title)}</b><div>${esc(x.text)}</div><div class="small muted">${fmt(x.created_at)}</div></div>`).join(''):'<div class="empty">Ничего не найдено</div>');document.querySelectorAll('[data-hit]').forEach(x=>x.onclick=()=>{closeModal();openChat(Number(x.dataset.hit))})}catch(e){notify(e.message,true)}}

  async function renderTickets(){top('Заявки','РАБОЧИЕ ПРОЦЕССЫ',`<button class="btn btn-primary" id="newTicket">+ Создать заявку</button>`);document.getElementById('content').innerHTML='<div id="ticketsBox" class="card"><div class="empty">Загрузка...</div></div>';document.getElementById('newTicket').onclick=()=>ticketForm(false);await loadTickets()}
  async function loadTickets(){try{const d=await api('/tickets?limit=100');const b=document.getElementById('ticketsBox');b.innerHTML=`<div class="section-head"><h3>Мои заявки</h3><span class="badge badge-blue">${d.total}</span></div>${d.items.length?table(['ID','Тема','Статус','Приоритет','Дата'],d.items.map(x=>[x.id,x.title,badge(x.status),x.priority,fmt(x.updated_at)])):'<div class="empty">Заявок пока нет</div>'}`}catch(e){notify(e.message,true)}}
  function ticketForm(incident){const p=S.profile;modal(incident?'Новый инцидент':'Новая заявка',`<div class="form-grid"><div class="field full"><label>ТЕМА</label><input id="fTitle" class="input"></div><div class="field full"><label>ОПИСАНИЕ</label><textarea id="fDesc" class="textarea"></textarea></div>${incident?'<div class="field"><label>ТИП</label><input id="fKind" class="input" value="GENERAL"></div><div class="field"><label>СЕРЬЁЗНОСТЬ</label><select id="fSev" class="select"><option>S1</option><option selected>S2</option><option>S3</option></select></div><div class="field"><label>МЕСТО</label><input id="fLoc" class="input"></div><div class="field"><label>ОБОРУДОВАНИЕ</label><input id="fEquip" class="input"></div>':'<div class="field"><label>КАТЕГОРИЯ</label><input id="fCat" class="input" value="GENERAL"></div>'}<div class="field"><label>ПРИОРИТЕТ</label><select id="fPriority" class="select"><option>LOW</option><option selected>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></div></div><button id="saveForm" class="btn btn-primary">Отправить</button>`);document.getElementById('saveForm').onclick=async()=>{try{if(incident){await api('/incidents',{method:'POST',body:{kind:val('fKind'),severity:val('fSev'),location:val('fLoc'),equipment:val('fEquip'),impact:'',department_id:p.enterprise,section_id:p.workshop,title:val('fTitle'),description:val('fDesc'),priority:val('fPriority')}})}else{await api('/tickets',{method:'POST',body:{type:'REQUEST',category:val('fCat'),department_id:p.enterprise,section_id:p.workshop,title:val('fTitle'),description:val('fDesc'),priority:val('fPriority')}})}closeModal();notify('Отправлено');incident?renderIncidents():loadTickets()}catch(e){notify(e.message,true)}}}
  async function renderIncidents(){top('Инциденты','БЕЗОПАСНОСТЬ И ПРОИЗВОДСТВО',`<button class="btn btn-primary" id="newIncident">+ Сообщить об инциденте</button>`);document.getElementById('content').innerHTML='<div id="incBox" class="card"><div class="empty">Загрузка...</div></div>';document.getElementById('newIncident').onclick=()=>ticketForm(true);try{const d=await api('/incidents?limit=100');document.getElementById('incBox').innerHTML=`<div class="section-head"><h3>Инциденты</h3><span class="badge badge-orange">${d.length}</span></div>${d.length?table(['ID','Тип','Статус','Серьёзность','Место','Дата'],d.map(x=>[x.id,x.kind,badge(x.status),x.severity,x.location||'—',fmt(x.updated_at)])):'<div class="empty">Инцидентов нет</div>'}`}catch(e){notify(e.message,true)}}

  function renderExams(){top('Экзамены Online / Offline','ОБУЧЕНИЕ И ПРОВЕРКА ЗНАНИЙ');const cached=Object.keys(localStorage).filter(k=>k.startsWith('mg_exam_pkg_')).map(k=>k.replace('mg_exam_pkg_',''));document.getElementById('content').innerHTML=`${S.offline?'<div class="offline-banner">Сервер недоступен. Можно проходить ранее загруженные офлайн-экзамены; ответы сохранятся на устройстве.</div>':''}<div class="grid grid-2"><div class="card"><h3>Online экзамен</h3><p class="muted">Выберите ключ экзамена и начните попытку.</p><div class="field"><label>ЭКЗАМЕН</label><select id="examKey" class="select"><option>OTTB</option><option>GPM</option></select></div><div class="actions"><button id="startOnline" class="btn btn-primary">Начать online</button><button id="downloadOffline" class="btn btn-soft">Скачать для offline</button></div></div><div class="card"><h3>Доступно offline</h3><p class="muted">Пакеты хранятся локально на этом устройстве.</p><div id="offlineList">${cached.length?cached.map(k=>`<div class="source"><b>${esc(k)}</b><button class="btn btn-ghost" data-offexam="${esc(k)}" style="float:right;padding:6px 10px">Начать</button></div>`).join(''):'<div class="empty">Пакеты ещё не загружены</div>'}</div></div></div><div id="examArea" style="margin-top:16px"></div>`;document.getElementById('startOnline').onclick=startOnlineExam;document.getElementById('downloadOffline').onclick=downloadOfflineExam;document.querySelectorAll('[data-offexam]').forEach(x=>x.onclick=()=>startOfflineExam(x.dataset.offexam));resumePendingSync()}
  async function startOnlineExam(){if(S.offline)return notify('Нет соединения с сервером',true);const key=val('examKey');try{const a=await api(`/exam/${key}/start`,{method:'POST'});S.exam={mode:'online',key,attempt:a.attempt_id,score:0,total:0};await nextOnlineQuestion()}catch(e){notify(e.message,true)}}
  async function nextOnlineQuestion(){try{const q=await api(`/exam/${S.exam.attempt}/next`);renderQuestion(q,async sel=>{const r=await api('/exam/answer',{method:'POST',body:{attempt_id:S.exam.attempt,question_id:q.id,selected:sel}});S.exam.total++;if(r.is_correct)S.exam.score++;notify(r.is_correct?'Правильно':'Неверно. Правильный ответ: '+r.correct,!r.is_correct);if(S.exam.total>=10)finishExam();else setTimeout(nextOnlineQuestion,500)})}catch(e){notify(e.message,true)}}
  async function downloadOfflineExam(){const key=val('examKey');try{const p=await api(`/exams/${key}/offline-package?limit=30`);localStorage.setItem('mg_exam_pkg_'+key,JSON.stringify(p));notify(`Экзамен ${key} сохранён offline`);renderExams()}catch(e){notify(e.message,true)}}
  function startOfflineExam(key){const p=JSON.parse(localStorage.getItem('mg_exam_pkg_'+key)||'null');if(!p?.questions?.length)return notify('Пакет пуст',true);S.exam={mode:'offline',key,idx:0,questions:p.questions.slice().sort(()=>Math.random()-.5).slice(0,10),answers:[],score:0,total:0,clientId:crypto.randomUUID?crypto.randomUUID():'off-'+Date.now()};nextOfflineQuestion()}
  function nextOfflineQuestion(){const q=S.exam.questions[S.exam.idx];if(!q)return finishExam();renderQuestion(q,sel=>{S.exam.answers.push({question_id:q.id,selected:sel});S.exam.total++;S.exam.idx++;nextOfflineQuestion()},true)}
  function parseOptions(x){if(Array.isArray(x))return x;try{const j=JSON.parse(x);if(Array.isArray(j))return j;if(j&&typeof j==='object')return Object.entries(j).map(([k,v])=>`${k}. ${v}`)}catch{}return String(x||'').split(/\n|\|/).filter(Boolean)}
  function renderQuestion(q,onAnswer,offline=false){const opts=parseOptions(q.options);document.getElementById('examArea').innerHTML=`<div class="card"><div class="section-head"><div><span class="badge badge-blue">${esc(q.topic||q.exam_key)}</span><span class="badge">${offline?'OFFLINE':'ONLINE'}</span></div><b>${S.exam.total+1}/10</b></div><div class="exam-question">${esc(q.question)}</div><div class="options">${opts.map((o,i)=>{const letter=String.fromCharCode(65+i);const m=String(o).match(/^([A-Z])\s*[.)-]\s*(.*)$/i);return `<div class="option" data-opt="${m?m[1].toUpperCase():letter}"><b>${m?m[1].toUpperCase():letter}</b> ${esc(m?m[2]:o)}</div>`}).join('')}</div></div>`;document.querySelectorAll('[data-opt]').forEach(x=>x.onclick=()=>onAnswer(x.dataset.opt))}
  function finishExam(){document.getElementById('examArea').innerHTML=`<div class="card"><h3>Экзамен завершён</h3><p>${S.exam.mode==='online'?`Результат текущих 10 вопросов: <b>${S.exam.score}/10</b>`:'Ответы сохранены локально. При появлении сети они будут синхронизированы с сервером.'}</p></div>`;if(S.exam.mode==='offline'){const k='mg_exam_pending_'+S.exam.clientId;localStorage.setItem(k,JSON.stringify({client_attempt_id:S.exam.clientId,exam_key:S.exam.key,answers:S.exam.answers}));resumePendingSync()}}
  async function resumePendingSync(){if(S.offline||!S.token)return;const keys=Object.keys(localStorage).filter(k=>k.startsWith('mg_exam_pending_'));for(const k of keys){try{const d=JSON.parse(localStorage.getItem(k));await api('/exams/offline-sync',{method:'POST',body:d});localStorage.removeItem(k);notify('Офлайн-экзамен синхронизирован')}catch{}}}

  async function renderItr(){top('AI-помощник ИТР','ТЕХНИЧЕСКАЯ БАЗА');document.getElementById('content').innerHTML=`<div class="grid grid-2"><div class="card"><h3>Спросить по оборудованию</h3><div class="field"><label>МОДЕЛЬ ОБОРУДОВАНИЯ (если известна)</label><input id="equipModel" class="input" placeholder="Например ABB ..."></div><div class="field"><label>ВОПРОС</label><textarea id="itrQ" class="textarea" placeholder="Покажи документы, регламент ТО, допустимые параметры..."></textarea></div><button id="itrAsk" class="btn btn-primary">✦ Найти по техдокументам</button><div class="muted small" style="margin-top:14px">Сейчас работает защищённый поиск по загруженной базе. Полный локальный RAG/распознавание шильдика подключается отдельным AI-этапом.</div></div><div class="card"><h3>Ответ и источники</h3><div id="itrResult" class="empty">Введите запрос слева</div></div></div>`;document.getElementById('itrAsk').onclick=async()=>{try{const r=await api('/itr/assistant',{method:'POST',body:{query:val('itrQ'),equipment_model:val('equipModel')}});document.getElementById('itrResult').innerHTML=`<div class="result-box">${esc(r.answer)}</div><h4>Найденные документы</h4>${r.sources?.length?r.sources.map(x=>`<div class="source"><b>${esc(x.title)}</b><div class="small muted">${esc(x.equipment_model||'')} • ${esc(x.doc_type)}</div></div>`).join(''):'<div class="empty">Совпадений нет</div>'}`}catch(e){notify(e.message,true)}}}
  async function renderPayroll(){top('Мои расчётные листы','ПЕРСОНАЛЬНЫЕ ДАННЫЕ');document.getElementById('content').innerHTML='<div class="empty">Загрузка...</div>';try{const d=await api('/me/payroll');document.getElementById('content').innerHTML=d.length?`<div class="grid grid-2">${d.map(x=>`<div class="card"><div class="section-head"><h3>${esc(x.period)}</h3><span class="badge badge-green">Личный доступ</span></div><div class="salary">${esc(x.net||'—')}</div><div class="muted small">К выплате</div><div class="salary-grid"><div class="salary-item"><span class="muted small">Начислено</span><b>${esc(x.gross||'—')}</b></div><div class="salary-item"><span class="muted small">Удержано</span><b>${esc(x.deductions||'—')}</b></div><div class="salary-item"><span class="muted small">К выплате</span><b>${esc(x.net||'—')}</b></div></div></div>`).join('')}</div>`:'<div class="card empty"><div class="empty-icon">₽</div>Расчётные листы ещё не загружены бухгалтерией</div>'}catch(e){notify(e.message,true)}}
  function renderProfile(){top('Профиль сотрудника','УЧЁТНАЯ ЗАПИСЬ');const p=S.profile;document.getElementById('content').innerHTML=`<div class="grid grid-2"><div class="card"><div class="user-row"><div class="avatar" style="width:64px;height:64px;font-size:22px">${esc(initials())}</div><div><h2 style="margin:0">${esc(p.full_name||p.id)}</h2><div class="muted">${esc(p.position||roleName(p.role))}</div></div></div><div style="height:18px"></div>${info('Табельный номер',p.tab_no||p.id)}${info('Предприятие',p.enterprise)}${info('Цех / подразделение',p.workshop)}${info('Роль',roleName(p.role))}${info('Доступ 1С / Directum',p.domain_apps_allowed?'Разрешён после интеграции':'Нет')}</div><div class="card"><h3>Сменить пароль</h3><div class="field"><label>ТЕКУЩИЙ ПАРОЛЬ</label><input id="oldPass" type="password" class="input"></div><div class="field"><label>НОВЫЙ ПАРОЛЬ</label><input id="newPass" type="password" class="input"></div><button id="changePass" class="btn btn-primary">Изменить пароль</button></div></div>`;document.getElementById('changePass').onclick=async()=>{try{await api('/me/change-password',{method:'POST',body:{current_password:val('oldPass'),new_password:val('newPass')}});notify('Пароль изменён')}catch(e){notify(e.message,true)}}}
  function info(a,b){return `<div style="padding:12px 0;border-bottom:1px solid var(--line)"><div class="small muted">${esc(a)}</div><div class="strong" style="margin-top:4px">${esc(b||'—')}</div></div>`}

  function renderAdmin(){top('Администрирование','ДОСТУП ТОЛЬКО ADMIN');document.getElementById('content').innerHTML=`<div class="grid grid-3"><div class="card"><h3>Импорт сотрудников</h3><p class="muted small">Excel: Ф.И.О., табельный номер, предприятие, цех, должность и другие поля.</p><input id="empFile" type="file" accept=".xlsx" class="input"><button id="empImport" class="btn btn-primary" style="margin-top:12px">Импортировать Excel</button><div id="empRes" class="result-box hidden"></div></div><div class="card"><h3>Расчётные листы</h3><div class="field"><label>ПЕРИОД</label><input id="payPeriod" class="input" placeholder="2026-08"></div><input id="payFile" type="file" accept=".xlsx" class="input"><button id="payImport" class="btn btn-primary" style="margin-top:12px">Распределить по сотрудникам</button></div><div class="card"><h3>Технический документ</h3><div class="field"><input id="tdTitle" class="input" placeholder="Название документа"></div><div class="field"><input id="tdModel" class="input" placeholder="Модель оборудования"></div><div class="field"><textarea id="tdText" class="textarea" placeholder="Текст / описание для поиска"></textarea></div><input id="tdFile" type="file" class="input"><button id="tdUpload" class="btn btn-primary" style="margin-top:12px">Добавить в техбазу</button></div></div>`;document.getElementById('empImport').onclick=()=>adminUploadEmployees();document.getElementById('payImport').onclick=()=>adminUploadPayroll();document.getElementById('tdUpload').onclick=()=>adminUploadTech()}
  async function adminUploadEmployees(){const f=document.getElementById('empFile').files[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{const r=await api('/admin/employees/import-xlsx',{method:'POST',body:fd});const el=document.getElementById('empRes');el.classList.remove('hidden');el.textContent=`Создано: ${r.created}\nОбновлено: ${r.updated}\nПропущено: ${r.skipped}\n\nВременные пароли сохраните безопасно:\n`+Object.entries(r.temporary_passwords||{}).map(([k,v])=>`${k}: ${v}`).join('\n');notify('Импорт завершён')}catch(e){notify(e.message,true)}}
  async function adminUploadPayroll(){const f=document.getElementById('payFile').files[0],period=val('payPeriod');if(!f||!period)return notify('Укажите период и файл',true);const fd=new FormData();fd.append('period',period);fd.append('file',f);try{const r=await api('/admin/payroll/import-xlsx',{method:'POST',body:fd});notify(`Распределено: ${r.imported}`)}catch(e){notify(e.message,true)}}
  async function adminUploadTech(){const fd=new FormData();fd.append('enterprise_id',S.profile.enterprise);fd.append('workshop_id',S.profile.workshop||'ALL');fd.append('equipment_model',val('tdModel'));fd.append('equipment_type','');fd.append('title',val('tdTitle'));fd.append('doc_type','MANUAL');fd.append('text_content',val('tdText'));const f=document.getElementById('tdFile').files[0];if(f)fd.append('file',f);try{await api('/admin/tech-docs',{method:'POST',body:fd});notify('Документ добавлен в техбазу')}catch(e){notify(e.message,true)}}

  function badge(x){const s=esc(x);return `<span class="badge ${/CLOSED|RESOLVED|DONE/i.test(x)?'badge-green':/HIGH|CRIT|ACTIVE/i.test(x)?'badge-orange':'badge-blue'}">${s}</span>`}
  function table(headers,rows){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${String(x).startsWith('<span')?x:esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
  function val(id){return document.getElementById(id)?.value?.trim()||''}
  function modal(title,body){closeModal();const d=document.createElement('div');d.id='modalBack';d.className='modal-backdrop';d.innerHTML=`<div class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button class="close" id="modalClose">×</button></div>${body}</div>`;document.body.appendChild(d);document.getElementById('modalClose').onclick=closeModal;d.onclick=e=>{if(e.target===d)closeModal()}}
  function closeModal(){document.getElementById('modalBack')?.remove()}
  addEventListener('online',()=>{S.offline=false;document.getElementById('netState')?.classList.remove('offline');if(document.getElementById('netState'))document.getElementById('netState').textContent='Сервер доступен';resumePendingSync()});addEventListener('offline',()=>{S.offline=true;document.getElementById('netState')?.classList.add('offline');if(document.getElementById('netState'))document.getElementById('netState').textContent='Офлайн'});
  if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
  if(S.token)bootstrap();else renderLogin();
})();
